COMMENT ON COLUMN llm_config.api_format IS '接口协议';
COMMENT ON COLUMN llm_config.temperature IS '温度';
COMMENT ON COLUMN llm_config.created_at IS '创建时间';
COMMENT ON COLUMN llm_config.updated_at IS '更新时间';

COMMENT ON TABLE llm_share IS 'API 共享';
COMMENT ON COLUMN llm_share.id IS '主键';
COMMENT ON COLUMN llm_share.config_id IS '共享配置';
COMMENT ON COLUMN llm_share.owner_user_id IS '所有者';
COMMENT ON COLUMN llm_share.target_user_id IS '被共享用户';
COMMENT ON COLUMN llm_share.created_at IS '共享时间';

COMMENT ON TABLE app_meta IS '应用元数据';
COMMENT ON COLUMN app_meta.key IS '键';
COMMENT ON COLUMN app_meta.value IS '值';

-- 卷号重排（幂等）：真考卷按创建先后 1..N 连续编号，刷题卷固定 0——
-- 修复旧版刷题卷占号导致的「第 3 / 2 张」卷号与张数口径不一致
UPDATE paper p SET sequence = s.rn
FROM (
    SELECT id, ROW_NUMBER() OVER (PARTITION BY user_id, practice_id ORDER BY sequence ASC, id ASC) AS rn
    FROM paper
    WHERE kind IS DISTINCT FROM 'drill'
) s
WHERE p.id = s.id AND p.sequence IS DISTINCT FROM s.rn;

UPDATE paper SET sequence = 0
WHERE kind = 'drill' AND sequence IS DISTINCT FROM 0;
